def verify_acrostic_poem(lines, head_target, embed_target):
    if len(lines) != 8:
        return False, "句数不为8"
    for i, line in enumerate(lines):
        if not line.startswith(head_target[i]):
            return False, f"第{i+1}句未以'{head_target[i]}'开头"
        if embed_target[i] not in line:
            return False, f"第{i+1}句未包含'{embed_target[i]}'"
    return True, "藏头与嵌字检查通过（注：诗意与押韵自然度需额外评估）"

def verify_water_radical(text, water_chars_set):
    chars = [c for c in text if '\u4e00' <= c <= '\u9fff']
    if len(chars) != 18:
        return False, f"汉字数量为{len(chars)}，不等于18"
    non_water = [c for c in chars if c not in water_chars_set]
    return len(non_water) == 0, f"违规汉字: {non_water}"

poem = [
    "计成二兔越山冈", "算到零时雪满塘", "机警狐衔二袋粮", "学随六雁辨风向",
    "院中九犬忽声扬", "真到月明逢恶狼", "牛守一夜迎晨光", "逼得日升狼遁荒"
]
print(verify_acrostic_poem(poem, "计算机学院真牛逼", "二零二六九月一日"))
